Lemma find_some_in : forall (A : Type) (p : A -> bool) l x, find p l = Some x -> In x l /\ p x = true.
Proof.
  intros A p l x. induction l as [|y l IH]; cbn; intros H; [discriminate|].
  destruct (p y) eqn:PY. - injection H; intros ->. auto. - destruct (IH H); auto.
Qed.

Lemma img_partials_eq : img_partials =
  map (fun r : Z * Z * Z => let '(q, sz, kq) := r in (q + sz / 8, sz mod 8))
      (List.filter (fun r : Z * Z * Z => let '(q, sz, kq) := r in negb (sz mod 8 =? 0)) img_globs).
Proof. vm_compute. reflexivity. Qed.

(* [comment removed for export] *)
Lemma img_shval_partial : forall g, img_shval g <> 0 -> img_shval g <> RZ -> In (g, img_shval g) img_partials.
Proof.
  intros g NZ NR. unfold img_shval in *.
  destruct (in_iv g tab_piv); [congruence|].
  destruct (find _ _) as [[[q sz] kq]|] eqn:F; [|congruence].
  apply find_some_in in F. destruct F as [IN _].
  unfold glob_val in *. destruct (_ && _) eqn:E; [|congruence].
  apply andb_prop in E. destruct E as [E1 E2]. rewrite Z.eqb_eq in E1. subst g.
  rewrite img_partials_eq. apply in_map_iff. exists (q, sz, kq). split; [reflexivity|]. apply filter_In. split; [exact IN|exact E2].
Qed.

